const TIME_UNITS: Readonly<Record<string, string>> = { phút: '分钟', giờ: '小时', ngày: '天' };
const NOTICE_LABELS = ['Tạo phản hồi thất bại', 'Phản hồi bị cắt ngang', 'Đang xin quyền', 'Mô hình chờ bạn trả lời'];

/** 只匹配完整工具模板，替换值按上屏契约限长，并原样保留正则/美元符号。 */
function toolSpeech(displayText: string): string | undefined {
  for (const [display, original] of TOOL_TEMPLATES) {
    const slot = display.includes('{target}') ? '{target}' : '{cmd}';
    const [prefix, suffix] = display.split(slot);
    if (!displayText.startsWith(prefix) || !displayText.endsWith(suffix)) continue;
    const value = displayText.slice(prefix.length, displayText.length - suffix.length);
    if (!value || value.trim() !== value || /\p{Cc}/u.test(value)) continue;
    if (Array.from(value).length > 20) continue;
    if (slot === '{cmd}' && !/^[A-Za-z][A-Za-z\d_.-]+$/.test(value)) continue;
    return original.split(slot).join(value);
  }
  return undefined;
}

type SpeechPart = { readonly text: string; readonly translate?: true };

/** 提醒只替换外壳与时间单位；待办正文单独标记为待翻译。 */
function todoSpeechParts(displayText: string): readonly SpeechPart[] | undefined {
  const due = /^"([^\r\n]+)" đến giờ rồi nè, nhớ làm nha$/u.exec(displayText);
  if (due?.[0] === displayText && validTodoLabel(due[1])) {
    return [{ text: '「' }, { text: due[1], translate: true }, { text: '」到点啦，记得处理' }];
  }
  const overdue = /^"([^\r\n]+)" đã trễ ([1-9]\d*) (phút|giờ|ngày) rồi đó, nhớ làm nha$/u.exec(displayText);
  if (overdue?.[0] === displayText && validTodoLabel(overdue[1])) {
    return [
      { text: '「' },
      { text: overdue[1], translate: true },
      { text: `」已经逾期${overdue[2]}${TIME_UNITS[overdue[3]]}啦，记得处理` },
    ];
  }
  const ahead = /^Còn ([1-9]\d*) (phút|giờ|ngày) nữa là đến giờ "([^\r\n]+)" rồi nè$/u.exec(displayText);
  if (ahead?.[0] === displayText && validTodoLabel(ahead[3])) {
    return [
      { text: '「' },
      { text: ahead[3], translate: true },
      { text: `」还有${ahead[1]}${TIME_UNITS[ahead[2]]}就到点啦` },
    ];
  }
  return undefined;
}

function validTodoLabel(label: string): boolean {
  const length = Array.from(label).length;
  return length <= 18 || (length === 19 && label.endsWith('…'));
}

function noticeSpeechParts(displayText: string): readonly SpeechPart[] | undefined {
  for (const label of NOTICE_LABELS) {
    const suffix = ' · ' + label;
    if (!displayText.endsWith(suffix)) continue;
    const name = displayText.slice(0, -suffix.length);
    if (!name || name.trim() !== name || name.length > 31 || /[\r\n]/u.test(name)) continue;
    return [{ text: name, translate: true }, { text: ' · ' + EXACT_SPEECH.get(label) }];
  }
  return undefined;
}

/**
 * 保留固定上游原话，仅标记待办正文与会话名供调用方单独翻译。
 *
 * @param displayText - 完整显示文本；不归一化空白或标点。
 * @returns 按原文顺序排列的语音片段；工具目标不标记，未知文本返回 undefined。
 */
export function originalSpeechParts(displayText: string): readonly SpeechPart[] | undefined {
  const exact = EXACT_SPEECH.get(displayText);
  if (exact !== undefined) return [{ text: exact }];
  const todo = todoSpeechParts(displayText);
  if (todo) return todo;
  const tool = toolSpeech(displayText);
  if (tool !== undefined) return [{ text: tool }];
  return noticeSpeechParts(displayText);
}

/**
 * 查找固定上游原话；返回值只供语音合成，调用方继续显示传入的越南语。
 *
 * @param displayText - 完整显示文本；不归一化空白或标点。
 * @returns 精确内置台词或完整模板的中文原文；未知文本返回 undefined，交给调用方处理。
 */
export function originalSpeechText(displayText: string): string | undefined {
  return originalSpeechParts(displayText)
    ?.map((part) => part.text)
    .join('');
}
